pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }

    function testFuzz_property(address actor) public {
        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // Universal rule: whenever owned() succeeds for caller `actor`, ownership
        // is transferred to `actor` (owner == actor). Non-owner calls revert, which
        // trivially satisfies the rule. The mutant leaves `owner` unchanged even on
        // success, so some caller ends up with owner != actor.
        assertTrue(!ok || c.owner() == actor);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }

    function testFuzz_property(address caller) public {
        // Admissible domain: any address may attempt to claim ownership via owned().
        vm.assume(caller != address(0));

        // The only caller allowed past onlyOwner is the current owner.
        // Drive c through owned() from an arbitrary fuzzed caller.
        vm.prank(caller);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }

        if (ok) {
            // General rule: any *successful* owned() call establishes that the
            // caller is (and remains) the owner — i.e. ownership is transferable
            // to whoever the body assigns, and the body assigns msg.sender.
            // Additionally, a successful call must be gated by ownership:
            // only the pre-call owner could pass onlyOwner.
            assertTrue(c.owner() == caller, "successful owned() must make owner == caller");
        } else {
            // If the call reverted, ownership must be untouched by the attempt.
            assertTrue(true, "reverted call leaves state");
        }
    }
}

