pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        c = new C(0, "", "");
        deployer = msg.sender;
    }

    function testFuzz_property(address caller) public {
        // Rule: any call to owned() from an address that is not the owner reverts;
        // any successful call must make owner == msg.sender.
        // Drive through owned() from the fuzzed caller.
        vm.prank(caller);
        bool ok;
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }
        if (ok) {
            // Successful owned() call: caller must now be the owner.
            assertTrue(c.owner() == caller && c.owner() == deployer);
        } else {
            // Reverted call: caller was not the owner; owner must be untouched.
            assertTrue(c.owner() != caller && c.owner() == deployer);
        }
    }
}

