pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        // Drive c through `owned` from the fuzzed caller.
        vm.prank(actor);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // Rule: the call either reverts, or, on success, ownership is (re)assigned
        // to the caller, so the owner equals the successful caller afterwards.
        assertTrue(!ok || c.owner() == actor);
    }
}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test() public {
    require(c.owner() == address(this));
    c.owned();
    assert(c.owner() == address(this));
  }
  receive() external payable {}
  fallback() external payable {}
}

