}

contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  function runTest(uint256 mintAmount, uint256 burnAmount) public {
    require(mintAmount > 0);
    require(burnAmount > 0 && burnAmount <= c.balanceOf(c.owner()));
    c.mintToken(c.owner(), mintAmount);
    uint256 before = c.totalSupply();
    c.burn(burnAmount);
    assert(c.totalSupply() == before - burnAmount);
  }

  receive() external payable {}
  fallback() external payable {}
}

