contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }
  function test(uint256 burnVal) public {
    require(c.owner() == address(this));
    uint256 beforeSupply = c.totalSupply();
    require(c.balanceOf(address(this)) >= burnVal);
    c.burn(burnVal);
    assert(c.totalSupply() == beforeSupply - burnVal);
  }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public {
        require(amount > 0);
        require(c.balanceOf(address(this)) >= amount);
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        c.burn(amount);
        uint256 supplyAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        assert(supplyAfter == supplyBefore - (balBefore - balAfter));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // Precondition: this test contract is the current owner (observable via public getter).
        require(address(this) == c.owner());
        bool reverted; try c.owned() { reverted = false; } catch { reverted = true; }   // boundary
        // Rule: the owner can always take ownership via owned(); the mutant inverts
        // the modifier so the owner's call reverts.
        assert(!reverted);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 v) public {
        require(v > 0);
        require(c.balanceOf(address(this)) >= v);
        uint256 supplyBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));
        c.burn(v);
        uint256 supplyAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));
        assert(supplyBefore - supplyAfter == v && balBefore - balAfter == supplyBefore - supplyAfter);
    }
    receive() external payable {}
}
